import java.time.LocalDate;

public class FlexibleDateParserTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object parsed(String text) {
        try {
            LocalDate date = FlexibleDateParser.parse(text);
            return date == null ? "<null>" : date.toString();
        } catch (Throwable crash) {
            return "parse threw " + crash.getClass().getSimpleName();
        }
    }

    static Object pattern(String text) {
        try {
            return FlexibleDateParser.matchedPattern(text);
        } catch (Throwable crash) {
            return "matchedPattern threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("ISO form", "2024-07-04", parsed("2024-07-04"));
        check("US slash form", "2024-07-04", parsed("7/4/2024"));
        check("spelled month form", "2024-07-04", parsed("4 Jul 2024"));
        check("surrounding spaces are trimmed", "2024-07-04", parsed("  7/4/2024  "));
        check("nonsense text", "<null>", parsed("not a date"));
        check("a month of 13 fits no pattern", "<null>", parsed("13/1/2024"));
        check("the reported pattern for the slash form", "M/d/yyyy", pattern("7/4/2024"));
        check("the reported pattern when nothing fits", "unknown", pattern("not a date"));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

