/**
 * TASK: Accept a date written in any of three formats.
 *
 * parse(text) tries these patterns IN ORDER, all with java.util.Locale.US:
 *   "yyyy-MM-dd"  e.g. "2024-07-04"
 *   "M/d/yyyy"    e.g. "7/4/2024"
 *   "d MMM yyyy"  e.g. "4 Jul 2024"
 * It returns the LocalDate from the first pattern that works, or null when the
 * text is null, blank, or matches none of them. Leading and trailing spaces are
 * trimmed before parsing.
 *
 * matchedPattern(text) returns the pattern string that worked -- "yyyy-MM-dd",
 * "M/d/yyyy" or "d MMM yyyy" -- or "unknown" when nothing parsed.
 *
 * A pattern that does not fit throws DateTimeParseException, so each attempt
 * belongs in its own try/catch: catching and moving on is how the fallback
 * chain works.
 *
 * Example: parse("7/4/2024") -> 2024-07-04, matchedPattern("7/4/2024") -> "M/d/yyyy"
 *          parse("13/1/2024") -> null (there is no month 13)
 */
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.Locale;

public class FlexibleDateParser {

    private static final String[] PATTERNS = {"yyyy-MM-dd", "M/d/yyyy", "d MMM yyyy"};

    public static LocalDate parse(String text) {
        if (text == null || text.trim().isEmpty()) {
            return null;
        }
        String cleaned = text.trim();
        for (String pattern : PATTERNS) {
            try {
                return LocalDate.parse(cleaned, DateTimeFormatter.ofPattern(pattern, Locale.US));
            } catch (DateTimeParseException wrongShape) {
                // this pattern does not fit -- try the next one
            }
        }
        return null;
    }

    public static String matchedPattern(String text) {
        if (text == null || text.trim().isEmpty()) {
            return "unknown";
        }
        String cleaned = text.trim();
        for (String pattern : PATTERNS) {
            try {
                LocalDate.parse(cleaned, DateTimeFormatter.ofPattern(pattern, Locale.US));
                return pattern;
            } catch (DateTimeParseException wrongShape) {
                // keep looking
            }
        }
        return "unknown";
    }
}
